"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["39602"],{88441(e){e.exports=JSON.parse('{"id":"V4-079","slug":"shareholder","term":"Shareholder","also_known_as":[],"difficulty":"Beginner","definition":"A shareholder is a person or organisation that owns shares in a company, making them a part-owner with rights such as voting on major decisions and receiving any dividends.","explanation":["Shareholders provide capital to companies by buying shares, either when the company issues them or from other investors on a stock exchange. In return, they own a portion of the company and share in its success through dividends and rising share prices. They also bear the risk of losses if the company does poorly.","Ordinary shareholders usually have voting rights, typically one vote per share, allowing them to elect directors and approve major decisions at general meetings. Preferred shareholders often have priority for dividends but limited voting rights.","For example, an investor who buys 100 shares of a company with 10,000,000 shares outstanding owns 0.001% of the company and receives that share of any dividends paid.","Shareholders\u2019 liability is usually limited to the amount they invested, so they cannot lose more than they put in. If a company fails, shareholders are paid last, after creditors, and often receive nothing. In the United States, the term stockholder is also common. Shareholders are one type of stakeholder, alongside employees, customers, suppliers and communities."],"note":"","total":1725,"prev":{"slug":"shared-ownership","term":"Shared Ownership"},"next":{"slug":"shareholder-activism","term":"Shareholder Activism"}}')}}]);